    background: #f7fafc;
    cursor: not-allowed;
}

.checkbox-text {
    font-size: 16px;
    font-weight: 500;
    color: #1a202c;
    line-height: 1.5;
    padding-top: 2px;
}

.helper-text {
    font-size: 14px;
    color: #718096;
    margin: 0;
    line-height: 1.5;
    margin-left: 32px;
}

.submit-btn {
    background: #667eea;
    color: white;
    border: none;
    padding: 12px 24px;
    font-size: 16px;
    font-weight: 600;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-top: 8px;
}

.submit-btn:hover:not(:disabled) {
    background: #5a67d8;
    transform: translateY(-1px);
    box-shadow: 0 8px 20px rgba(102, 126, 234, 0.3);
}

.submit-btn:active:not(:disabled) {
    transform: translateY(0);
}

.submit-btn:disabled {
    background: #cbd5e0;
    cursor: not-allowed;
    opacity: 0.6;
}

.success-message {
    background: #f0fdf4;
    border: 1px solid #86efac;
    color: #166534;
    padding: 16px;
    border-radius: 8px;
    text-align: center;
    font-size: 16px;
    font-weight: 500;
    margin-top: 12px;
    animation: slideIn 0.3s ease;
}

@keyframes slideIn {
    from {
